'use strict';

// MODULES //

var hasSymbolSupport = require( '@stdlib/assert/has-symbol-support' );


// MAIN //

/**
* Symbol.toStringTag.
*
* @name ToStringTagSymbol
* @constant
* @type {(symbol|null)}
*/
var ToStringTagSymbol = ( hasSymbolSupport() ) ? Symbol.toStringTag : null;


// EXPORTS //

module.exports = ToStringTagSymbol;
